def select(model) -> list:
    walls = by_type(elements_in_storey(model, "Ground Floor"), "IfcWall")
    return by_name(walls, "Basic Wall:Wall-Ext_102Bwk-75Ins-100LBlk-12P:285330")

def modify(model, targets) -> None:
    for wall in targets:
        pset = element.get_pset(wall, "Pset_WallCommon")
        if pset:
            pset = model.by_id(pset["id"])
        else:
            pset = ifcopenshell.api.run("pset.add_pset", model, product=wall, name="Pset_WallCommon")
        ifcopenshell.api.run("pset.edit_pset", model, pset=pset, properties={"ThermalTransmittance": 0.18})

